R=lambda root,o,zh,ja,ez,ej,ex: dict(root=root,origin=o,zh=zh,ja=ja,exp_zh=ez,exp_ja=ej,examples=ex)
roots=[R('-sol-','Latin solus','单独；唯一','ひとつだけ；唯一','来自拉丁语 solus（单独的）。唯一的 → sole；独自的 → solo；孤独的 → solitary；荒凉 → desolate。⚠️ isolate / isolation 来自 insula（岛），意义相近但不同源；console（安慰）也不是此词根。','ラテン語 solus（ひとつだけの）から。唯一の → sole；単独の → solo；孤独な → solitary；荒れ果てた → desolate。isolate / isolation は insula（島）由来で別源。console（慰める）もこの語根ではない。',[w['w'] for w in sol]),
R('-pur-','Latin purus','纯净；干净','清い；純粋な','来自拉丁语 purus（干净的、纯的）。纯的 → pure；使纯净 → purify；清除 → purge；不纯 → impure。⚠️ purpose（目的）与此无关。','ラテン語 purus（清い・純粋な）から。純粋な → pure；浄化する → purify；一掃する → purge；不純な → impure。purpose（目的）は無関係。',[w['w'] for w in pur]),
R('mal-','Latin male / malus','坏；不良','悪い；不良','来自拉丁语 male（坏地）/ malus（坏的）。恶意 → malice；渎职 → malpractice；营养不良 → malnutrition；故障 → malfunction（已学）。⚠️ mall（购物中心）、male（男性）不是此词根。','ラテン語 male（悪く）/ malus（悪い）から。悪意 → malice；業務上の過失 → malpractice；栄養不良 → malnutrition。mall（ショッピングモール）や male（男性）は別語。',[w['w'] for w in mal]),
R('-pun- / -pen-','Latin poena','惩罚；刑罚','罰；刑罰','来自拉丁语 poena（刑罚，原为希腊语借词）。惩罚 → punish；惩罚性的 → punitive；刑罚的 → penal；不受罚 → impunity；后悔 → repent。⚠️ pen（笔）、pending（待定）不是此词根。','ラテン語 poena（刑罰、ギリシャ語由来）から。罰する → punish；懲罰的 → punitive；刑罰の → penal；罰を受けない → impunity；悔いる → repent。pen（ペン）や pending（未決）は別語。',[w['w'] for w in pun])]
